  org: { slug: string; name: string; keyPrefix: string };
}

const ROLE_RANK: Record<Role, number> = { CREW_MEMBER: 0, MISSION_LEAD: 1, DIRECTOR: 2 };

/** Role hierarchy: DIRECTOR ⊃ MISSION_LEAD ⊃ CREW_MEMBER. */
export function hasRoleAtLeast(actor: Pick<Actor, 'role'>, role: Role): boolean {
  return ROLE_RANK[actor.role] >= ROLE_RANK[role];
}

export const ROLE_LABEL: Record<Role, string> = {
  DIRECTOR: 'Director',
  MISSION_LEAD: 'Mission Lead',
  CREW_MEMBER: 'Crew Member',
};

/** Assignment statuses that occupy a seat. */
export const LIVE_SEAT_STATUSES: readonly AssignmentStatus[] = ['PROPOSED', 'OFFERED', 'ACCEPTED'];

export const TERMINAL_MISSION_STATUSES: readonly MissionStatus[] = ['COMPLETED', 'CANCELLED'];

export function missionKey(keyPrefix: string, number: number): string {
  return `${keyPrefix}-${number}`;
}

/**
 * Mission lifecycle and permissions as data.
 *
 * One table answers "who may do what, in which state". It drives:
 *   - enforcement      (assertMissionAction, called by every mission service)
 *   - discoverability  (allowedMissionActions → `allowedActions` in API responses → CLI hints)
 *   - tests            (tests/unit/lifecycle.test.ts walks every status × action × role)
 *
 * State guards that need data (e.g. "every role is fully nominated") live in the
 * services; this table only covers state + actor.
 */
import { AppError, forbidden } from '../lib/errors.js';
import type { Actor, MissionStatus } from './types.js';
import { hasRoleAtLeast } from './types.js';

export type MissionAction =
  | 'edit'
  | 'nominate'
  | 'submit'
  | 'approve'
  | 'reject'
  | 'cancel'
  | 'offer'
  | 'activate'
  | 'complete'
  | 'match';

/** Who may perform an action, relative to the mission. */
export type ActorRule = 'owner' | 'director' | 'directorNotOwner' | 'ownerOrDirector' | 'leadOrAbove';

export interface MissionRule {
  action: MissionAction;
  from: readonly MissionStatus[];
  to?: MissionStatus;
  who: ActorRule;
  summary: string;
}

const NON_TERMINAL: readonly MissionStatus[] = ['DRAFT', 'SUBMITTED', 'REJECTED', 'APPROVED', 'ACTIVE'];

export const MISSION_RULES: readonly MissionRule[] = [
  { action: 'edit', from: ['DRAFT', 'REJECTED'], who: 'owner', summary: 'change title, dates or roles' },
  { action: 'match', from: NON_TERMINAL, who: 'leadOrAbove', summary: 'run the matcher (dry run)' },
  { action: 'nominate', from: ['DRAFT', 'REJECTED'], who: 'owner', summary: 'nominate crew (hidden from crew until approval)' },
  { action: 'submit', from: ['DRAFT', 'REJECTED'], to: 'SUBMITTED', who: 'owner', summary: 'send plan + nominated crew for approval' },
  { action: 'approve', from: ['SUBMITTED'], to: 'APPROVED', who: 'directorNotOwner', summary: 'approve — offers go to the nominated crew' },
  { action: 'reject', from: ['SUBMITTED'], to: 'REJECTED', who: 'directorNotOwner', summary: 'send back for changes' },
  { action: 'cancel', from: NON_TERMINAL, to: 'CANCELLED', who: 'director', summary: 'scrap the mission — releases all crew' },
  { action: 'offer', from: ['APPROVED', 'ACTIVE'], who: 'owner', summary: 'backfill open seats or retract offers' },
  { action: 'activate', from: ['APPROVED'], to: 'ACTIVE', who: 'owner', summary: 'lock the crew (every seat accepted)' },
  { action: 'complete', from: ['ACTIVE'], to: 'COMPLETED', who: 'ownerOrDirector', summary: 'close out the mission' },
];

export interface MissionRef {
  status: MissionStatus;
  ownerId: string;
}

export function ruleFor(action: MissionAction): MissionRule {
  const rule = MISSION_RULES.find((candidate) => candidate.action === action);
  if (!rule) throw new Error(`No lifecycle rule for action "${action}"`);
  return rule;
}

function actorAllowed(rule: ActorRule, actor: Actor, mission: MissionRef): boolean {
  const isOwner = actor.userId === mission.ownerId;
  const isDirector = actor.role === 'DIRECTOR';
  switch (rule) {
    case 'owner':
      return isOwner;
    case 'director':
      return isDirector;
    case 'directorNotOwner':
      return isDirector && !isOwner;
    case 'ownerOrDirector':
      return isOwner || isDirector;
    case 'leadOrAbove':
      return hasRoleAtLeast(actor, 'MISSION_LEAD');
  }
}

function actorError(rule: MissionRule, actor: Actor, mission: MissionRef): AppError {
  if (rule.who === 'directorNotOwner' && actor.role === 'DIRECTOR' && actor.userId === mission.ownerId) {
    return new AppError(
      'CANNOT_APPROVE_OWN',
      'You created this mission, so you cannot review it. Another director must approve or reject it.',
    );
  }
  const who: Record<ActorRule, string> = {
    owner: "the mission's owner",
    director: 'a director',
    directorNotOwner: 'a director who did not create the mission',
    ownerOrDirector: "the mission's owner or a director",
    leadOrAbove: 'mission leads and directors',
  };
  return forbidden(`Only ${who[rule.who]} can ${rule.summary}.`);
}

/** Throws FORBIDDEN / CANNOT_APPROVE_OWN (actor) or INVALID_TRANSITION (state). Actor is checked first. */
export function assertMissionAction(action: MissionAction, mission: MissionRef, actor: Actor): MissionRule {
  const rule = ruleFor(action);
  if (!actorAllowed(rule.who, actor, mission)) throw actorError(rule, actor, mission);
  if (!rule.from.includes(mission.status)) {
    throw new AppError(
      'INVALID_TRANSITION',
      `Cannot ${action} a mission that is ${mission.status}. Allowed from: ${rule.from.join(', ')}.`,
      { status: mission.status, action, allowedFrom: rule.from },
    );
  }
  return rule;
}

export function canPerform(action: MissionAction, mission: MissionRef, actor: Actor): boolean {
  const rule = ruleFor(action);
  return rule.from.includes(mission.status) && actorAllowed(rule.who, actor, mission);
}

/** Actions this actor may take on this mission right now (state + actor only). */
export function allowedMissionActions(mission: MissionRef, actor: Actor): MissionAction[] {
  return MISSION_RULES.filter((rule) => canPerform(rule.action, mission, actor)).map((rule) => rule.action);
}

/**
 * Schedule rules shared by the matcher (who is eligible?) and the accept flow
 * (can this person still take the seat?). One implementation, so the matcher
 * never recommends someone the server would then refuse, and vice versa.
 *
 *   UNAVAILABLE  — the person blocked out days inside the mission window
 *   CONFLICT     — the person holds an accepted seat on an overlapping mission
 *   REST_GAP     — fewer than the org's rest days between this mission and another
 *                  (pre-flight quarantine / post-flight recovery)
 */
import { formatRange, gapBetween, overlaps, type DayRange } from '../lib/dates.js';

export interface Commitment {
  missionId: string;
  missionKey: string;
  range: DayRange;
}

export type ScheduleIssue =
  | { kind: 'UNAVAILABLE'; range: DayRange }
  | { kind: 'CONFLICT'; missionKey: string; range: DayRange }
  | { kind: 'REST_GAP'; missionKey: string; range: DayRange; gapDays: number; requiredDays: number };

export interface ScheduleSubject {
  unavailable: readonly DayRange[];
  commitments: readonly Commitment[];
}

export function scheduleIssues(
  window: DayRange,
  subject: ScheduleSubject,
  restGapDays: number,
  ignoreMissionId?: string,
): ScheduleIssue[] {
  const issues: ScheduleIssue[] = [];
  for (const range of subject.unavailable) {
    if (overlaps(window, range)) issues.push({ kind: 'UNAVAILABLE', range });
  }
  for (const commitment of subject.commitments) {
    if (commitment.missionId === ignoreMissionId) continue;
    if (overlaps(window, commitment.range)) {
      issues.push({ kind: 'CONFLICT', missionKey: commitment.missionKey, range: commitment.range });
      continue;
    }
    const gapDays = gapBetween(window, commitment.range);
    if (gapDays < restGapDays) {
      issues.push({
        kind: 'REST_GAP',
        missionKey: commitment.missionKey,
        range: commitment.range,
        gapDays,
        requiredDays: restGapDays,
      });
    }
  }
  return issues;
}

export function describeScheduleIssue(issue: ScheduleIssue): string {
  switch (issue.kind) {
    case 'UNAVAILABLE':
      return `unavailable ${formatRange(issue.range)}`;
    case 'CONFLICT':
      return `committed to ${issue.missionKey} (${formatRange(issue.range)})`;
    case 'REST_GAP':
      return `only ${issue.gapDays} rest day${issue.gapDays === 1 ? '' : 's'} around ${issue.missionKey} (org requires ${issue.requiredDays})`;
  }
}

