/** Request schemas (zod). Shape validation only; business rules live in the services. */
import { z } from 'zod';
import { AppError } from '../lib/errors.js';
import { parseIsoDate } from '../lib/dates.js';

export function parse<T>(schema: z.ZodType<T>, data: unknown): T {
  const result = schema.safeParse(data ?? {});
  if (result.success) return result.data;
  const details = result.error.issues.map((issue) => ({
    path: issue.path.map(String).join('.') || '(body)',
    message: issue.message,
  }));
  const first = details[0];
  throw new AppError(
    'VALIDATION_FAILED',
    first ? `Invalid request: ${first.path} — ${first.message}` : 'Invalid request',
    details,
  );
}

export const isoDate = z
  .string()
  .refine((value) => parseIsoDate(value) !== null, { message: 'must be a real date in YYYY-MM-DD format' })
  .transform((value) => parseIsoDate(value)!);

const text = (max: number) => z.string().trim().min(1, 'must not be empty').max(max);

export const handle = z.string().trim().min(1).max(40);
export const skillKey = z
  .string()
  .trim()
  .toLowerCase()
  .regex(/^[a-z][a-z0-9-]{0,23}$/, 'use lowercase letters, digits and dashes (max 24), e.g. "nav"');
export const level = z.number().int().min(1, 'levels run 1–5').max(5, 'levels run 1–5');

export const roleSpec = z.strictObject({
  name: text(60),
  headcount: z.number().int().min(1).max(20),
  skills: z
    .array(z.strictObject({ skill: skillKey, min: level }))
    .min(1, 'each role needs at least one skill requirement')
    .max(10),
});

export const createMissionBody = z.strictObject({
  title: text(120),
  description: z.string().trim().max(2000).optional(),
  startDate: isoDate,
  endDate: isoDate,
  roles: z.array(roleSpec).max(20).optional(),
});

export const updateMissionBody = z
  .strictObject({
    title: text(120).optional(),
    description: z.string().trim().max(2000).nullable().optional(),
    startDate: isoDate.optional(),
    endDate: isoDate.optional(),
  })
  .refine((body) => Object.values(body).some((value) => value !== undefined), { message: 'nothing to update' });

export const rolesBody = z.strictObject({ roles: z.array(roleSpec).min(1).max(20) });

export const seatRequestBody = z.union([
  z.strictObject({ recommended: z.literal(true), reset: z.boolean().optional() }),
  z.strictObject({ role: text(60), crew: handle, reset: z.boolean().optional() }),
]);

export const noteBody = z.strictObject({ note: z.string().trim().max(1000).optional() });
export const requiredNoteBody = z.strictObject({ note: text(1000) });
export const reasonBody = z.strictObject({ reason: text(500) });
export const optionalReasonBody = z.strictObject({ reason: z.string().trim().max(500).optional() });

export const skillsBody = z.strictObject({
  skills: z.array(z.strictObject({ skill: skillKey, level })).min(1).max(30),
});

export const unavailabilityBody = z.strictObject({
  startDate: isoDate,
  endDate: isoDate,
  note: z.string().trim().max(200).optional(),
});

export const settingsBody = z
  .strictObject({
    restGapDays: z.number().int().min(0).max(120).optional(),
    offerTtlDays: z.number().int().min(1).max(30).optional(),
  })
  .refine((body) => body.restGapDays !== undefined || body.offerTtlDays !== undefined, { message: 'nothing to update' });

export const createSkillBody = z.strictObject({
  key: skillKey,
  name: text(60),
  description: z.string().trim().max(200).optional(),
});

export const listMissionsQuery = z.object({
  status: z
    .string()
    .optional()
    .transform((value) => (value ? value.split(',').map((part) => part.trim().toUpperCase()).filter(Boolean) : undefined))
    .pipe(z.array(z.enum(['DRAFT', 'SUBMITTED', 'REJECTED', 'APPROVED', 'ACTIVE', 'COMPLETED', 'CANCELLED'])).optional()),
  mine: z
    .enum(['true', 'false'])
    .optional()
    .transform((value) => value === 'true'),
});

export const crewQuery = z.object({
  skill: z.string().trim().optional(),
  min: z.coerce.number().int().min(1).max(5).optional(),
});

export const matchQuery = z.object({ explain: handle.optional() });

/**
 * HTTP layer: authentication, error mapping and routing. Controllers are thin —
 * parse the request, build the service context, call one service function.
 */
import Fastify, { type FastifyInstance, type FastifyRequest } from 'fastify';
import { Prisma, type PrismaClient } from '@prisma/client';
import { AppError } from '../lib/errors.js';
import { systemClock, type Clock } from '../lib/clock.js';
import { hashToken } from '../lib/tokens.js';
import type { Actor } from '../domain/types.js';
import type { Ctx } from '../services/context.js';
import { registerMissionRoutes } from './routes/missions.js';
import { registerMeRoutes } from './routes/me.js';
import { registerOrgRoutes } from './routes/org.js';

declare module 'fastify' {
  interface FastifyRequest {
    actor: Actor | null;
  }
}

export interface AppDeps {
  db: PrismaClient;
  clock?: Clock;
  logger?: boolean | { level: string };
}

export type ContextFor = (request: FastifyRequest) => Ctx;

export function buildApp(deps: AppDeps): FastifyInstance {
  const clock = deps.clock ?? systemClock;
  const app = Fastify({ logger: deps.logger ?? false });
  app.decorateRequest('actor', null);

  // Token → (user, org, role). The org is always derived from the token.
  app.addHook('onRequest', async (request) => {
    if (request.url === '/v1/health') return;
    const header = request.headers.authorization ?? '';
    const token = /^Bearer\s+(.+)$/i.exec(header)?.[1]?.trim();
    if (!token) throw new AppError('UNAUTHENTICATED', 'Missing API token. Log in with `mc login <token>`.');
    const user = await deps.db.user.findUnique({ where: { tokenHash: hashToken(token) }, include: { org: true } });
    if (!user) throw new AppError('UNAUTHENTICATED', 'That API token is not valid.');
    request.actor = {
      userId: user.id,
      orgId: user.orgId,
      role: user.role,
      handle: user.handle,
      name: user.name,
      org: { slug: user.org.slug, name: user.org.name, keyPrefix: user.org.keyPrefix },
    };
  });

  const ctx: ContextFor = (request) => {
    if (!request.actor) throw new AppError('UNAUTHENTICATED', 'Not authenticated.');
    return { db: deps.db, clock, actor: request.actor };
  };

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) return reply.status(error.status).send(error.toJSON());
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      if (error.code === 'P2002') {
        return reply.status(409).send(new AppError('DUPLICATE', 'That record already exists.').toJSON());
      }
      if (error.code === 'P2003') {
        // Composite (org_id, id) foreign keys make cross-tenant references impossible at the database level.
        return reply
          .status(422)
          .send(new AppError('VALIDATION_FAILED', 'A referenced record does not exist in your organisation.').toJSON());
      }
    }
    const status = (error as { statusCode?: number }).statusCode;
    if (status && status >= 400 && status < 500) {
      const message = error instanceof Error ? error.message : 'Bad request';
      return reply.status(400).send(new AppError('VALIDATION_FAILED', message).toJSON());
    }
    request.log.error(error);
    return reply.status(500).send(new AppError('INTERNAL', 'Something went wrong on the server.').toJSON());
  });

  app.setNotFoundHandler((request, reply) =>
    reply.status(404).send(new AppError('ROUTE_NOT_FOUND', `No route ${request.method} ${request.url}`).toJSON()),
  );

  app.get('/v1/health', async () => {
    await deps.db.$queryRaw`SELECT 1`;
    return { status: 'ok' };
  });

  registerMeRoutes(app, ctx);
  registerOrgRoutes(app, ctx);
  registerMissionRoutes(app, ctx);
  return app;
}

import type { FastifyInstance } from 'fastify';
import type { ContextFor } from '../app.js';
import { getInbox } from '../../services/inbox.js';
import { getMe } from '../../services/org.js';
import { acceptOffer, declineOffer, dropOut, listMyOffers } from '../../services/offers.js';
import {
  addUnavailability,
  getMyProfile,
  removeMySkill,
  removeUnavailability,
  setMySkills,
} from '../../services/people.js';
import { optionalReasonBody, parse, reasonBody, skillsBody, unavailabilityBody } from '../validation.js';

type KeyParams = { Params: { key: string } };

export function registerMeRoutes(app: FastifyInstance, ctx: ContextFor): void {
  app.get('/v1/me', async (request) => getMe(ctx(request)));
  app.get('/v1/inbox', async (request) => getInbox(ctx(request)));

  app.get('/v1/me/profile', async (request) => getMyProfile(ctx(request)));
  app.put('/v1/me/skills', async (request) => setMySkills(ctx(request), parse(skillsBody, request.body).skills));
  app.delete<{ Params: { key: string } }>('/v1/me/skills/:key', async (request) => removeMySkill(ctx(request), request.params.key));

  app.get('/v1/me/unavailability', async (request) => (await getMyProfile(ctx(request))).unavailable);
  app.post('/v1/me/unavailability', async (request, reply) => {
    const created = await addUnavailability(ctx(request), parse(unavailabilityBody, request.body));
    return reply.status(201).send(created);
  });
  app.delete<{ Params: { id: string } }>('/v1/me/unavailability/:id', async (request) =>
    removeUnavailability(ctx(request), request.params.id),
  );

  app.get('/v1/me/offers', async (request) => listMyOffers(ctx(request)));
  app.post<KeyParams>('/v1/me/offers/:key/accept', async (request) => acceptOffer(ctx(request), request.params.key));
  app.post<KeyParams>('/v1/me/offers/:key/decline', async (request) =>
    declineOffer(ctx(request), request.params.key, parse(optionalReasonBody, request.body).reason),
  );
  app.post<KeyParams>('/v1/me/offers/:key/drop', async (request) =>
    dropOut(ctx(request), request.params.key, parse(reasonBody, request.body).reason),
  );
}

import type { FastifyInstance } from 'fastify';
import type { ContextFor } from '../app.js';
import { createSkill, getSettings, listSkills, updateSettings } from '../../services/org.js';
import { getCrewMember, listCrew } from '../../services/people.js';
import { createSkillBody, crewQuery, parse, settingsBody } from '../validation.js';

export function registerOrgRoutes(app: FastifyInstance, ctx: ContextFor): void {
