      actorId: ctx.actor.userId,
      type: 'CREW_DROPPED_OUT',
      payload: { crew: ctx.actor.handle, role: offer.role.name, reason: reason.trim() },
    });
    return { key: missionKey(ctx.actor.org.keyPrefix, mission.number), status: 'DROPPED' };
  });
}

