  t = t.split(from).join('return withLockedMission(ctx, key, async (db, mission) => {');
  t = t.replace("import { recordEvent, tx, type Ctx, type Db } from './context.js';", "import { recordEvent, type Ctx, type Db } from './context.js';");
  t = t.replace("import { loadMission } from './missions.js';", "import { loadMission, withLockedMission } from './missions.js';");
  return t;
});

