  const from = 'const mission = await tx(ctx, async (db) => {\n    const current = await loadMission(ctx, key, db);';
  if (count(t, from) !== 8) throw new Error('missions pattern count ' + count(t, from));
  t = t.split(from).join('const mission = await withLockedMission(ctx, key, async (db, current) => {');
  const anchor = 'function keyOf(ctx: Ctx, mission: { number: number }): string {';
  t = t.replace(anchor, `/**
 * Resolve the key (with the visibility check) outside the transaction — the
 * key → id mapping never changes — then lock the mission row and re-read it as
 * the first thing inside. Every write to a mission or its seats goes through here.
 */
export async function withLockedMission<T>(
  ctx: Ctx,
  key: string,
  fn: (db: Prisma.TransactionClient, mission: Mission) => Promise<T>,
): Promise<T> {
  const ref = await loadMission(ctx, key);
  return tx(ctx, async (db) => {
    await lockMission(db, ctx.actor.orgId, ref.id);
    const mission = await db.mission.findFirstOrThrow({ where: { id: ref.id, orgId: ctx.actor.orgId } });
    return fn(db, mission);
  });
}

` + anchor);
  t = t.replace("import { moveMission, parseMissionKey, recordEvent, tx, type Ctx, type Db } from './context.js';", "import { lockMission, moveMission, parseMissionKey, recordEvent, tx, type Ctx, type Db } from './context.js';");
  return t;
});
console.log('ok');
