import { createServer } from 'node:net';
import { PrismaClient } from '@prisma/client';
import { config } from './config.js';
import { buildApp } from './http/app.js';
import { clearServerRecord, writeServerRecord } from './lib/discovery.js';

/** How many ports to try, starting at PORT, before giving up. */
const PORT_ATTEMPTS = 20;

/** True if nothing is listening on host:port (probe with a throwaway socket). */
function portIsFree(port: number, host: string): Promise<boolean> {
  return new Promise((resolve) => {
    const probe = createServer();
    probe.once('error', () => resolve(false)); // EADDRINUSE, or EACCES for ports Windows reserves
    probe.once('listening', () => probe.close(() => resolve(true)));
    probe.listen(port, host);
  });
}

export async function findFreePort(start: number, host: string, attempts = PORT_ATTEMPTS): Promise<number> {
  for (let port = start; port < start + attempts; port += 1) {
    if (await portIsFree(port, host)) return port;
  }
  throw new Error(`No free port between ${start} and ${start + attempts - 1}. Set PORT in .env to another range.`);
}

const db = new PrismaClient();
const app = buildApp({ db, logger: { level: config.logLevel, redact: ['req.headers.authorization'] } });

const shutdown = async (): Promise<void> => {
  clearServerRecord(process.pid);
  await app.close();
  await db.$disconnect();
  process.exit(0);
};
