    const view = await world.as('marcus').get(`/v1/missions/${key}`);
    expect(view.body.reviews.map((review: { round: number; decision: string }) => [review.round, review.decision])).toEqual([
      [2, 'APPROVED'],
      [1, 'REJECTED'],
    ]);
  });
});

