        }
      } else if (roll < 0.8) {
        const mission = pick(await missionsOf(org, ['APPROVED', 'ACTIVE']));
        if (mission) {
          const offered = await world.db.assignment.findFirst({ where: { missionId: mission.id, status: 'OFFERED' }, include: { user: true } });
