2	import { CliError, resolveProfile, type ResolvedProfile } from './config.js';
3	
4	/**
5	 * Exit codes (documented in README):
6	 *   0 ok · 1 unexpected · 2 usage · 3 not logged in / bad token · 4 forbidden
7	 *   5 not found · 6 state conflict or precondition · 7 invalid input · 8 API unreachable / not Mission Control
8	 */
9	const EXIT_BY_STATUS: Record<number, number> = { 400: 7, 401: 3, 403: 4, 404: 5, 409: 6, 422: 6 };
10	
11	export interface Client {
12	  profile: ResolvedProfile;
13	  get<T>(path: string): Promise<T>;
14	  post<T>(path: string, body?: unknown): Promise<T>;
15	  put<T>(path: string, body?: unknown): Promise<T>;
16	  patch<T>(path: string, body?: unknown): Promise<T>;
17	  delete<T>(path: string): Promise<T>;
18	}
19	
20	interface ApiErrorBody {
21	  error: { code: string; message: string; details?: unknown };
22	}
23	
24	function isApiErrorBody(value: unknown): value is ApiErrorBody {
25	  const error = (value as { error?: { code?: unknown; message?: unknown } } | null)?.error;
26	  return typeof error?.code === 'string' && typeof error.message === 'string';
27	}
28	
29	const unreachable = (apiUrl: string) =>
30	  new CliError(
31	    `Can't reach the Mission Control API at ${apiUrl}. Start it with \`npm run dev\` (it picks a free port and the CLI finds it), then try again.`,
32	    8,
33	  );
34	
35	/** Something answered, but it is not Mission Control — typically another dev server on the same port. */
36	export function notMissionControl(apiUrl: string, detail: string): CliError {
37	  return new CliError(
38	    `The server at ${apiUrl} isn't the Mission Control API (${detail}). Another app is probably using that port. ` +
39	      'Start Mission Control with `npm run dev` — it moves to a free port if 3000 is taken, and the CLI finds it automatically. ' +
40	      'Or point the CLI at it with MC_API_URL.',
41	    8,
42	  );
43	}
44	
45	async function parseBody(response: Response, apiUrl: string): Promise<unknown> {
46	  const text = await response.text();
47	  if (!text) return null;
48	  try {
49	    return JSON.parse(text) as unknown;
50	  } catch {
51	    const type = response.headers.get('content-type') ?? 'unknown content';
52	    throw notMissionControl(apiUrl, `it replied with ${type.includes('html') ? 'a web page' : type}, HTTP ${response.status}`);
53	  }
54	}
55	
56	export async function call<T>(
57	  target: { apiUrl: string; token?: string },
58	  method: string,
59	  path: string,
60	  body?: unknown,
61	): Promise<T> {
62	  let response: Response;
63	  try {
64	    response = await fetch(new URL(path, target.apiUrl), {
65	      method,
66	      headers: {
67	        ...(target.token ? { authorization: `Bearer ${target.token}` } : {}),
68	        ...(body === undefined ? {} : { 'content-type': 'application/json' }),
69	      },
70	      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
71	    });
72	  } catch {
73	    throw unreachable(target.apiUrl);
74	  }
75	  const payload = await parseBody(response, target.apiUrl);
76	  if (!response.ok) {
77	    if (!isApiErrorBody(payload)) throw notMissionControl(target.apiUrl, `HTTP ${response.status} without a Mission Control error body`);
78	    const hint = response.status === 401 ? ' Log in again with `mc login <token>`.' : '';
79	    throw new CliError(`${payload.error.message}${hint}`, EXIT_BY_STATUS[response.status] ?? 1, payload.error.code, payload.error.details);
80	  }
81	  // Minimal shape check: every Mission Control endpoint returns a JSON object or array.
82	  if (payload === null || typeof payload !== 'object') {
83	    throw notMissionControl(target.apiUrl, 'the response was not a JSON object');
84	  }
85	  return payload as T;
86	}
87	
88	export interface Health {
89	  status: string;
90	  service: string;
91	  version?: string;
92	}
93	
94	/** Confirms the URL is a live Mission Control API (used by login and doctor). */
95	export async function checkHealth(apiUrl: string): Promise<Health> {
96	  const health = await call<Partial<Health>>({ apiUrl }, 'GET', '/v1/health');
97	  if (health.service !== 'mission-control') {
98	    throw notMissionControl(apiUrl, 'its /v1/health does not identify as mission-control');
99	  }
100	  return { status: String(health.status), service: health.service, version: health.version };
101	}
102	
103	export function client(profileFlag?: string): Client {
104	  const profile = resolveProfile(profileFlag);
105	  const target = { apiUrl: profile.apiUrl, token: profile.token };
106	  return {
107	    profile,
108	    get: (path) => call(target, 'GET', path),
109	    post: (path, body) => call(target, 'POST', path, body),
110	    put: (path, body) => call(target, 'PUT', path, body),
111	    patch: (path, body) => call(target, 'PATCH', path, body),
112	    delete: (path) => call(target, 'DELETE', path),
113	  };
114	}
