1	/**
2	 * npm run demo — the whole Mission Control story, end to end, through the real
3	 * CLI and API, against a throwaway database. Your dev database and CLI profiles
4	 * are untouched.
5	 *
6	 * It doubles as a smoke test: every step declares the exit code it expects,
7	 * and the script exits non-zero if anything behaves differently.
8	 */
9	import { execFileSync, spawn } from 'node:child_process';
10	import { mkdtempSync, rmSync } from 'node:fs';
11	import { tmpdir } from 'node:os';
12	import path from 'node:path';
13	import { PrismaClient } from '@prisma/client';
14	import { buildApp } from '../src/http/app.js';
15	
16	const color = Boolean(process.stdout.isTTY) && !process.env.NO_COLOR;
17	const paint = (code: number) => (text: string) => (color ? `\u001b[${code}m${text}\u001b[0m` : text);
18	const bold = paint(1);
19	const dim = paint(2);
20	const cyan = paint(36);
21	const red = paint(31);
22	const green = paint(32);
23	
24	const dir = mkdtempSync(path.join(tmpdir(), 'mc-demo-'));
25	const databaseUrl = `file:${path.join(dir, 'demo.db').split(path.sep).join('/')}`;
26	const env = { ...process.env, DATABASE_URL: databaseUrl, PRISMA_HIDE_UPDATE_MESSAGE: '1' };
27	
28	console.log(dim('Preparing a throwaway database (migrate + seed)…'));
29	execFileSync(process.execPath, [path.resolve('node_modules/prisma/build/index.js'), 'migrate', 'deploy'], { env, stdio: 'pipe' });
30	execFileSync(process.execPath, [path.resolve('node_modules/tsx/dist/cli.mjs'), 'prisma/seed.ts'], { env, stdio: 'pipe' });
31	
32	const db = new PrismaClient({ datasourceUrl: databaseUrl });
33	const app = buildApp({ db });
34	const apiUrl = await app.listen({ port: 0, host: '127.0.0.1' });
35	
36	const PEOPLE: Record<string, { org: string; label: string }> = {
37	  marcus: { org: 'astra', label: 'Marcus Chen · Mission Lead · Astra Dynamics' },
38	  priya: { org: 'astra', label: 'Priya Nair · Mission Lead · Astra Dynamics' },
39	  ava: { org: 'astra', label: 'Ava Sterling · Director · Astra Dynamics' },
40	  jamal: { org: 'astra', label: 'Jamal Reyes · Crew · Astra Dynamics' },
41	  leo: { org: 'astra', label: 'Leo Vasquez · Crew · Astra Dynamics' },
42	  yuki: { org: 'astra', label: 'Yuki Tanaka · Crew · Astra Dynamics' },
43	  sara: { org: 'astra', label: 'Sara Lindqvist · Crew · Astra Dynamics' },
44	  owen: { org: 'lunar', label: 'Owen Park · Mission Lead · Lunar Collective (another tenant)' },
45	};
46	
47	let current = '';
48	let steps = 0;
49	const failures: string[] = [];
50	
51	function chapter(title: string): void {
52	  console.log(`\n\n${bold(`▌ ${title}`)}`);
53	}
54	
55	/** The API runs in this process, so the CLI must be spawned asynchronously (a sync spawn would deadlock). */
56	function runCli(args: string[], childEnv: NodeJS.ProcessEnv): Promise<{ status: number | null; output: string }> {
57	  return new Promise((resolve, reject) => {
58	    const child = spawn(process.execPath, [path.resolve('bin/mc.mjs'), ...args], { env: childEnv });
59	    let output = '';
60	    child.stdout.on('data', (chunk: Buffer) => (output += chunk.toString('utf8')));
61	    child.stderr.on('data', (chunk: Buffer) => (output += chunk.toString('utf8')));
62	    child.on('error', reject);
63	    child.on('close', (status) => resolve({ status, output }));
64	  });
65	}
66	
67	async function step(who: string, args: string[], options: { expectExit?: number; say?: string } = {}): Promise<void> {
68	  const expectExit = options.expectExit ?? 0;
69	  const person = PEOPLE[who]!;
70	  if (who !== current) {
71	    console.log(`\n${cyan(`━━ ${person.label} ━━`)}`);
72	    current = who;
73	  }
74	  if (options.say) console.log(dim(`   # ${options.say}`));
75	  const shown = args.map((arg) => (/\s/.test(arg) ? `"${arg}"` : arg)).join(' ');
76	  console.log(`${bold('$')} mc ${shown}`);
77	  const result = await runCli(args, {
78	    ...process.env,
79	    MC_TOKEN: `mct_${person.org}_${who}`,
80	    MC_API_URL: apiUrl,
81	    MC_CONFIG_DIR: dir,
82	    FORCE_COLOR: color ? '1' : '0',
83	    ...(color ? {} : { NO_COLOR: '1' }),
84	  });
85	  process.stdout.write(result.output);
86	  steps += 1;
87	  if (result.status !== expectExit) {
88	    failures.push(`mc ${shown} (as ${who}) exited ${result.status}, expected ${expectExit}`);
89	    console.log(red(`   ✗ expected exit ${expectExit}, got ${result.status}`));
90	  } else if (expectExit !== 0) {
91	    console.log(dim(`   (exit ${result.status}, as expected)`));
92	  }
93	}
94	
95	try {
96	  chapter('1 · A lead plans the crew — the matcher explains every choice');
97	  await step('marcus', ['inbox']);
98	  await step('marcus', ['missions', 'match', 'AST-6']);
99	  await step('marcus', ['missions', 'match', 'AST-6', '--explain', 'elena'], { say: 'Why isn’t Elena on it?' });
100	  await step('marcus', ['missions', 'nominate', 'AST-6', '--recommended']);
101	  await step('marcus', ['missions', 'submit', 'AST-6']);
102	
103	  chapter('2 · The director reviews the plan and the named crew');
104	  await step('ava', ['inbox']);
105	  await step('ava', ['missions', 'show', 'AST-6'], { say: 'The plan and the named crew, with scores' });
106	  await step('ava', ['missions', 'approve', 'AST-6', '--note', 'Good crew. Go.']);
107	  await step('ava', ['missions', 'reject', 'AST-8', '--note', 'Navigator must also be EVA-qualified; add it and resubmit.']);
108	
109	  chapter('3 · Crew respond — several offers are fine, double booking is not');
110	  await step('jamal', ['offers']);
111	  await step('jamal', ['offers', 'accept', 'AST-6']);
112	  await step('jamal', ['offers', 'accept', 'AST-7'], { expectExit: 6, say: 'AST-7 overlaps the mission he just accepted' });
113	  await step('priya', ['inbox'], { say: 'The other lead learns the seat is blocked — but not why' });
114	  await step('priya', ['missions', 'retract', 'AST-7', 'jamal']);
115	  await step('leo', ['offers', 'accept', 'AST-6']);
116	  await step('yuki', ['offers', 'accept', 'AST-6']);
117	
118	  chapter('4 · A drop-out after approval: repair the seat, not the mission');
119	  await step('yuki', ['offers', 'drop', 'AST-6', '--reason', 'Medical hold', '--yes']);
120	  await step('marcus', ['inbox']);
121	  await step('marcus', ['missions', 'match', 'AST-6'], { say: 'Nobody qualifies — the matcher says exactly why, and who is close' });
122	  await step('sara', ['profile', 'skills', 'set', 'nav=4'], { say: 'Sara completes her navigation recertification' });
123	  await step('marcus', ['missions', 'offer', 'AST-6', '--recommended']);
124	  await step('sara', ['offers', 'accept', 'AST-6']);
125	
126	  chapter('5 · Lock the crew; the roster is revealed to them');
127	  await step('marcus', ['missions', 'activate', 'AST-6']);
128	  await step('leo', ['missions', 'show', 'AST-6']);
129	
130	  chapter('6 · Tenancy and audit');
131	  await step('owen', ['missions', 'show', 'AST-6'], { expectExit: 5, say: 'Another organisation cannot even see that AST-6 exists' });
132	  await step('marcus', ['missions', 'history', 'AST-6']);
133	} finally {
134	  await app.close();
135	  await db.$disconnect();
136	  rmSync(dir, { recursive: true, force: true });
137	}
138	
139	console.log('');
140	if (failures.length > 0) {
141	  console.log(red(`✗ ${failures.length} of ${steps} steps behaved unexpectedly:`));
142	  for (const failure of failures) console.log(red(`  - ${failure}`));
