// Checks relative links (and #anchors into markdown files) in the given markdown files.
const fs = require('fs');
const path = require('path');
const root = 'C:/Users/shubh/OneDrive/Documents/Mutinex/mission-control';
const files = process.argv.slice(2);

// GitHub-style heading slugs.
const slugs = (file) => {
  const set = new Set();
  let inFence = false;
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    if (line.startsWith('```')) inFence = !inFence;
    if (inFence) continue;
    const m = /^#{1,6}\s+(.*)$/.exec(line);
    if (!m) continue;
    const text = m[1].replace(/`/g, '').replace(/\*\*/g, '').trim().toLowerCase();
    set.add(text.replace(/[^\p{L}\p{N}\s_-]/gu, '').replace(/\s/g, '-'));
  }
  return set;
};

let bad = 0;
let checked = 0;
for (const rel of files) {
  const file = path.join(root, rel);
  const text = fs.readFileSync(file, 'utf8');
  for (const [, target] of text.matchAll(/\]\(([^)\s]+)\)/g)) {
    if (/^https?:/.test(target)) continue;
    checked += 1;
    const [p, anchor] = target.split('#');
    const resolved = p ? path.resolve(path.dirname(file), p) : file;
    if (!fs.existsSync(resolved)) {
      console.log(`${rel}: missing ${target}`);
      bad += 1;
      continue;
    }
    if (anchor && resolved.endsWith('.md') && !slugs(resolved).has(anchor)) {
      console.log(`${rel}: no heading for #${anchor} in ${p || rel}`);
      bad += 1;
    }
  }
}
console.log(`${checked} relative links checked, ${bad} broken`);
process.exitCode = bad ? 1 : 0;

